import { mkdir } from 'node:fs/promises'
import path from 'node:path'

import StyleDictionary from 'style-dictionary'

const TOKENS_HEADER =
  '/* GENERATED by scripts/build-tokens.mjs from tokens/app.json — do not edit. */\n'

/**
 * Build the Style Dictionary instance for design tokens.
 *
 * Extracted from the CLI so tests can generate the file into a temporary
 * directory and compare it with the committed `_tokens.scss` byte for byte.
 */
function createTokensDictionary({ source, outputDir }) {
  const buildPath = outputDir.replace(/\\/g, '/')

  return new StyleDictionary({
    source: [source],
    hooks: {
      formats: {
        'scss/tokens-layer': ({ dictionary }) => {
          const lines = dictionary.allTokens.map(
            (token) => `    --${token.name}: ${token.value};`,
          )
          return `${TOKENS_HEADER}@layer tokens {\n  :root {\n${lines.join('\n')}\n  }\n}\n`
        },
      },
    },
    platforms: {
      scss: {
        transformGroup: 'css',
        buildPath: `${buildPath}/`,
        files: [{ destination: '_tokens.scss', format: 'scss/tokens-layer' }],
      },
    },
  })
}

/** Generate `_tokens.scss` from a DTCG token file. Returns the output path. */
export async function buildTokens({ source, outputDir }) {
  await mkdir(outputDir, { recursive: true })

  const dictionary = createTokensDictionary({ source, outputDir })
  await dictionary.buildAllPlatforms()

  return path.join(outputDir, '_tokens.scss')
}
